import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.Cs11k9ph.js";const q=JSON.parse('{"title":"❓ 常见问题（v2.7）","description":"","frontmatter":{},"headers":[],"relativePath":"v2.7/faq.md","filePath":"v2.7/faq.md","lastUpdated":1788070985000}'),l={name:"v2.7/faq.md"};function r(o,a,n,h,d,p){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="❓-常见问题-v2-7" tabindex="-1">❓ 常见问题（v2.7） <a class="header-anchor" href="#❓-常见问题-v2-7" aria-label="Permalink to &quot;❓ 常见问题（v2.7）&quot;">​</a></h1><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>本文档为 <strong>v2.7 旧版归档</strong>。最新版本请参考 <a href="/faq.html">v2.8 常见问题</a>。</p></div><h2 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h2><h3 id="q-无法启动客户端怎么办" tabindex="-1">Q: 无法启动客户端怎么办？ <a class="header-anchor" href="#q-无法启动客户端怎么办" aria-label="Permalink to &quot;Q: 无法启动客户端怎么办？&quot;">​</a></h3><p><strong>A:</strong> 请按以下步骤排查：</p><ol><li>确认已安装 .NET 10.0 及以上运行时</li><li>检查客户端目录文件是否完整（不要缺少 DLL）</li><li>查看日志文件 <code>logs/client.log</code> 获取详细错误信息</li><li>尝试以管理员身份运行</li></ol><h3 id="q-服务器启动后端口被占用" tabindex="-1">Q: 服务器启动后端口被占用？ <a class="header-anchor" href="#q-服务器启动后端口被占用" aria-label="Permalink to &quot;Q: 服务器启动后端口被占用？&quot;">​</a></h3><p><strong>A:</strong> 端口 5000 被占用时，使用其他端口启动：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet CheckIn.Server.dll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">urls </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://0.0.0.0:5001&quot;</span></span></code></pre></div><p>同时需要修改客户端配置中的服务器地址。</p><hr><h2 id="连接问题" tabindex="-1">连接问题 <a class="header-anchor" href="#连接问题" aria-label="Permalink to &quot;连接问题&quot;">​</a></h2><h3 id="q-客户端连接不上服务器" tabindex="-1">Q: 客户端连接不上服务器？ <a class="header-anchor" href="#q-客户端连接不上服务器" aria-label="Permalink to &quot;Q: 客户端连接不上服务器？&quot;">​</a></h3><p><strong>A:</strong> 依次检查：</p><ol><li>服务器是否已启动？</li><li>防火墙是否放行 5000 端口？</li><li>客户端配置的 <code>ServerUrl</code> 是否正确？</li><li>客户端与服务器是否在同一局域网？</li></ol><h3 id="q-连接时提示-rsa-签名验证失败" tabindex="-1">Q: 连接时提示 RSA 签名验证失败？ <a class="header-anchor" href="#q-连接时提示-rsa-签名验证失败" aria-label="Permalink to &quot;Q: 连接时提示 RSA 签名验证失败？&quot;">​</a></h3><p><strong>A:</strong> 说明客户端与服务器密钥不匹配。请确保：</p><ul><li>使用同一版本的程序</li><li>不要混用不同版本的程序</li><li>重新下载对应版本的客户端和服务器</li></ul><hr><h2 id="使用问题" tabindex="-1">使用问题 <a class="header-anchor" href="#使用问题" aria-label="Permalink to &quot;使用问题&quot;">​</a></h2><h3 id="q-如何将学生名单批量导入" tabindex="-1">Q: 如何将学生名单批量导入？ <a class="header-anchor" href="#q-如何将学生名单批量导入" aria-label="Permalink to &quot;Q: 如何将学生名单批量导入？&quot;">​</a></h3><p><strong>A:</strong> 在 Web 管理面板中，进入&quot;任务管理&quot;页面，使用&quot;导入 CSV&quot;功能。CSV 格式要求：</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">姓名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">张三</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">李四</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">王五</span></span></code></pre></div><h3 id="q-签到数据如何导出" tabindex="-1">Q: 签到数据如何导出？ <a class="header-anchor" href="#q-签到数据如何导出" aria-label="Permalink to &quot;Q: 签到数据如何导出？&quot;">​</a></h3><p><strong>A:</strong> 在 Web 管理面板&quot;数据管理&quot;中，点击&quot;导出 CSV&quot;按钮，即可下载全部签到记录。</p><h3 id="q-不小心签错人怎么办" tabindex="-1">Q: 不小心签错人怎么办？ <a class="header-anchor" href="#q-不小心签错人怎么办" aria-label="Permalink to &quot;Q: 不小心签错人怎么办？&quot;">​</a></h3><p><strong>A:</strong> 在客户端大屏上，右键点击误签的学生姓名即可取消签到。</p><h3 id="q-排行榜数据是实时的吗" tabindex="-1">Q: 排行榜数据是实时的吗？ <a class="header-anchor" href="#q-排行榜数据是实时的吗" aria-label="Permalink to &quot;Q: 排行榜数据是实时的吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，排行榜实时更新。只有签到成功的记录才会进入排行榜。</p><hr><h2 id="数据与安全" tabindex="-1">数据与安全 <a class="header-anchor" href="#数据与安全" aria-label="Permalink to &quot;数据与安全&quot;">​</a></h2><h3 id="q-数据存储在哪里" tabindex="-1">Q: 数据存储在哪里？ <a class="header-anchor" href="#q-数据存储在哪里" aria-label="Permalink to &quot;Q: 数据存储在哪里？&quot;">​</a></h3><p><strong>A:</strong> 所有数据存储在服务器目录下的 SQLite 数据库中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CheckIn.Server/data/signwave.db</span></span></code></pre></div><h3 id="q-如何备份数据" tabindex="-1">Q: 如何备份数据？ <a class="header-anchor" href="#q-如何备份数据" aria-label="Permalink to &quot;Q: 如何备份数据？&quot;">​</a></h3><p><strong>A:</strong> 直接复制数据库文件即可，详细步骤见 <a href="/v2.7/deploy.html#数据库管理">部署指南 →</a>。</p><h3 id="q-清空数据前需要确认吗" tabindex="-1">Q: 清空数据前需要确认吗？ <a class="header-anchor" href="#q-清空数据前需要确认吗" aria-label="Permalink to &quot;Q: 清空数据前需要确认吗？&quot;">​</a></h3><p><strong>A:</strong> 需要。系统会要求三次确认，防止误操作。建议清空前先导出 CSV 备份。</p><h3 id="q-通信是否加密" tabindex="-1">Q: 通信是否加密？ <a class="header-anchor" href="#q-通信是否加密" aria-label="Permalink to &quot;Q: 通信是否加密？&quot;">​</a></h3><p><strong>A:</strong> 是的。客户端与服务器通信采用 RSA-2048 签名验证 + HMAC-SHA256 完整性校验，防止数据被篡改。</p><hr><h2 id="版本相关" tabindex="-1">版本相关 <a class="header-anchor" href="#版本相关" aria-label="Permalink to &quot;版本相关&quot;">​</a></h2><h3 id="q-如何升级到新版本" tabindex="-1">Q: 如何升级到新版本？ <a class="header-anchor" href="#q-如何升级到新版本" aria-label="Permalink to &quot;Q: 如何升级到新版本？&quot;">​</a></h3><p><strong>A:</strong> 按照 <a href="/v2.7/deploy.html#版本升级">部署指南 →</a> 中的升级步骤操作，升级前务必备份数据库。</p><h3 id="q-升级后数据会丢失吗" tabindex="-1">Q: 升级后数据会丢失吗？ <a class="header-anchor" href="#q-升级后数据会丢失吗" aria-label="Permalink to &quot;Q: 升级后数据会丢失吗？&quot;">​</a></h3><p><strong>A:</strong> 不会。只要数据库文件 <code>signwave.db</code> 存在，升级后数据依然保留。但强烈建议升级前手动备份。</p>`,46)])])}const u=e(l,[["render",r]]);export{q as __pageData,u as default};
